  constructor() {
    console.log(this.describe());   // dispatches to the override
  }
  describe(): string { return 'base'; }
}

class Child extends Base {
  name = 'child';                    // runs after super() returns
  describe(): string { return `I am ${this.name}`; }
}

new Child();                          // I am undefined

