class Account {
  static opened = 0;                 // on Account itself
  #cents = 0;                        // private slot on each instance
  readonly log: string[] = [];       // own field on each instance

  constructor(readonly id: string) { Account.opened++; }

  get balance(): number { return this.#cents; }   // on Account.prototype
  deposit(cents: number): void { this.#cents += cents; this.log.push(`+${cents}`); }
  onClick = () => this.deposit(1);   // own property: one closure per instance
}

