interface Channel { send(to: string, text: string): Promise<void> }

const email: Channel = { async send(to, text) { /* SMTP */ } };
const sms: Channel = { async send(to, text) { /* gateway */ } };

function withRetry(channel: Channel, attempts = 3): Channel {
  return {
    async send(to, text) {
      for (let i = 1; ; i++) {
        try { return await channel.send(to, text); }
        catch (error) { if (i >= attempts) throw error; }
      }
    },
  };
}

