interface Clock { now(): number }
interface Store<V> {
  get(key: string): V | undefined;
  set(key: string, value: V): void;
  delete(key: string): void;
}

class MapStore<V> implements Store<V> {
  readonly #map = new Map<string, V>();
  get(key: string): V | undefined { return this.#map.get(key); }
  set(key: string, value: V): void { this.#map.set(key, value); }
  delete(key: string): void { this.#map.delete(key); }
}

interface Entry<V> { readonly value: V; readonly expires: number }

class TtlCache<V> {
  constructor(
    private readonly store: Store<Entry<V>>,   // composed, not inherited
    private readonly clock: Clock,
    private readonly ttlMs: number,
  ) {}

  get(key: string): V | undefined {
    const entry = this.store.get(key);
    if (!entry) return undefined;
    if (entry.expires <= this.clock.now()) {
      this.store.delete(key);
      return undefined;
    }
    return entry.value;
  }

  set(key: string, value: V): void {
    this.store.set(key, { value, expires: this.clock.now() + this.ttlMs });
  }
}

let t = 0;
const fakeClock: Clock = { now: () => t };       // tests control time
const cache = new TtlCache<string>(new MapStore(), fakeClock, 1000);
cache.set('user:1', 'Ada');
t = 999;
console.log(cache.get('user:1'));   // Ada
t = 1000;
console.log(cache.get('user:1'));   // undefined

