class Account {
  balance: number;

  constructor(public id: string, openingCents = 0) {
    this.balance = openingCents;
  }

  deposit(cents: number): number {
    this.balance += cents;
    return this.balance;
  }

  withdraw(cents: number): number {
    // TODO: validate amounts, refuse overdrafts, and stop outside code writing balance or id
    this.balance -= cents;
    return this.balance;
  }
}

type LedgerOp = [kind: 'open' | 'deposit' | 'withdraw' | 'balance', id: string, cents?: number];

function runLedger(ops: readonly LedgerOp[]): Array<number | string> {
  const accounts = new Map<string, Account>();
  return ops.map(([kind, id, cents = 0]) => {
    try {
      if (kind === 'open') {
        if (accounts.has(id)) throw new Error('duplicate account');
        const account = new Account(id, cents);
        accounts.set(id, account);
        return account.balance;
      }
      const account = accounts.get(id);
      if (!account) throw new Error('unknown account');
      if (kind === 'deposit') return account.deposit(cents);
      if (kind === 'withdraw') return account.withdraw(cents);
      return account.balance;
    } catch (error) {
      return error instanceof Error ? error.message : String(error);
    }
  });
}

solution:
class Account {
  #cents: number;

  constructor(readonly id: string, openingCents = 0) {
    Account.#check(openingCents, true);
    this.#cents = openingCents;
  }

  get balance(): number {
    return this.#cents;
  }

  deposit(cents: number): number {
    Account.#check(cents);
    this.#cents += cents;
    return this.#cents;
  }

  withdraw(cents: number): number {
    Account.#check(cents);
    if (cents > this.#cents) throw new RangeError('insufficient funds');
    this.#cents -= cents;
    return this.#cents;
  }

  static #check(cents: number, allowZero = false): void {
    if (!Number.isInteger(cents) || cents < 0 || (cents === 0 && !allowZero)) {
      throw new RangeError('invalid amount');
    }
  }
}

`#cents` is a JavaScript private name, so no code outside the class body can read or write it, even with a cast or bracket access, and it is invisible to `Object.keys` and `JSON.stringify`. The `balance` getter is the only way out, and because it has no setter TypeScript treats `acct.balance = 5` as an error. The parameter property `readonly id` declares and assigns the id in one place. Every entry point funnels through the single `static #check`, so the invariant (a non-negative integer number of cents) is enforced once; the overdraft test happens before mutation, so a failed call leaves the state untouched. Because the class has a `#` member, TypeScript stops matching it structurally: an object literal with the same public members is no longer an `Account`. Each operation is O(1).

