function pipe<A, B>(f1: (a: A) => B): (a: A) => B;
function pipe<A, B, C>(f1: (a: A) => B, f2: (b: B) => C): (a: A) => C;
function pipe<A, B, C, D>(f1: (a: A) => B, f2: (b: B) => C, f3: (c: C) => D): (a: A) => D;
function pipe<A, B, C, D, E>(f1: (a: A) => B, f2: (b: B) => C, f3: (c: C) => D, f4: (d: D) => E): (a: A) => E;
function pipe<A, B, C, D, E, F>(f1: (a: A) => B, f2: (b: B) => C, f3: (c: C) => D, f4: (d: D) => E, f5: (e: E) => F): (a: A) => F;
function pipe(...fns: Array<(value: never) => unknown>): (value: unknown) => unknown {
  return (value: unknown) => fns.reduce<unknown>((acc, fn) => (fn as (v: unknown) => unknown)(acc), value);
}

const stripAccents = (s: string): string => s.normalize('NFKD').replace(/[\u0300-\u036f]/g, '');
const lower = (s: string): string => s.toLowerCase();
const dashify = (s: string): string => s.replace(/[^a-z0-9]+/g, '-');
const trimDashes = (s: string): string => s.replace(/^-+|-+$/g, '');

const toSlug = pipe(stripAccents, lower, dashify, trimDashes);

function slugify(title: string): string {
  return toSlug(title);
}

function memoize<A extends unknown[], R>(
  fn: (...args: A) => R,
  keyOf: (...args: A) => string = (...args) => JSON.stringify(args),
): (...args: A) => R {
  const cache = new Map<string, R>();
  return (...args: A): R => {
    const key = keyOf(...args);
    if (cache.has(key)) return cache.get(key) as R;
    const value = fn(...args);
    cache.set(key, value);
    return value;
  };
}

