function memoize(fn: (...args: any[]) => any): (...args: any[]) => any {
  const cache = new Map<string, any>();
  return (...args) => {
    // TODO: String(args) collides ([1] vs ['1'], every object is '[object Object]') and ?? forgets undefined results
    const key = String(args);
    return cache.get(key) ?? (cache.set(key, fn(...args)), cache.get(key));
  };
}

function countComputations(argLists: unknown[][]): number {
  let computed = 0;
  const probe = memoize((...args: unknown[]): undefined => {
    computed++;
    return undefined;
  });
  for (const args of argLists) probe(...args);
  return computed;
}

